#!/usr/bin/env python3
import sys

def main():
    # Read input
    with open('/workdir/data/parking.txt', 'r') as f:
        lines = f.read().strip().split('\n')

    n, m = map(int, lines[0].split())
    grid = lines[1:n+1]

    # Validate grid dimensions
    assert len(grid) == n
    for row in grid:
        assert len(row) == m

    # left[i][j] = number of consecutive '.' cells to the left ending at (i, j)
    left = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                left[i][j] = (left[i][j-1] + 1) if j > 0 else 1
            else:
                left[i][j] = 0

    # up[i][j] = number of consecutive '.' cells above ending at (i, j)
    up = [[0] * m for _ in range(n)]
    for j in range(m):
        for i in range(n):
            if grid[i][j] == '.':
                up[i][j] = (up[i-1][j] + 1) if i > 0 else 1
            else:
                up[i][j] = 0

    # diff[h][w] for difference array: diff[h][w] will be used to compute answer[h][w]
    # diff[h][0..m] array, we'll use size m+1
    diff = [[0] * (m + 1) for _ in range(n)]

    # For each cell (i, j), process the vertical run
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                continue

            # up[i][j] tells us how many consecutive '.' cells are above (including) (i,j)
            # We need to consider rectangles with bottom-right at (i,j)
            # For height H from 1 to up[i][j], the max width is min(left[k][j] for k in [i-H+1, i])

            # Compute running minimum of left values going up
            cur_min = float('inf')
