                # The row is i - h + 1
                row = i - h + 1
                cur_min = min(cur_min, left[row][j])
                # cur_min is now the min left value for rows [i-h+1, i]
                # This means for a tent of height h, the max width is cur_min
                # So we add 1 to answer[h-1][0..cur_min-1]
                # Using difference array: diff[h-1][0] += 1, diff[h-1][cur_min] -= 1
                diff[h-1][0] += 1
                if cur_min <= m:
                    diff[h-1][cur_min] -= 1
                # If cur_min > m, we don't need to subtract (but cur_min is at most m+1 effectively since left values are at most m)
                # Actually left values are in [0, m], so cur_min is in [0, m]. If cur_min=0, then diff[h-1][0] -= 1 cancels the +=1, which is correct (no valid widths).

    # Compute answer from diff using prefix sums
    answer = [[0] * m for _ in range(n)]
    for h in range(n):
        current = 0
        for w in range(m):
            current += diff[h][w]
            answer[h][w] = current

    # Write output
    with open('/workdir/answer.txt', 'w') as f:
        for row in answer:
            f.write(' '.join(map(str, row)) + '\n')

if __name__ == '__main__':
    main()
